import { useState } from "react";
import C from "../constants/colors";
import { SCHEMES } from "../constants/data";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";

function Schemes({ user }) {
  const [open, setOpen] = useState(null);
  return (
    <div style={{ padding:22 }}>
      <h1 style={{ fontSize:21, fontWeight:600, color:C.text, margin:"0 0 4px" }}>🏛️ Government Schemes</h1>
      <p style={{ color:C.muted, fontSize:13, margin:"0 0 6px" }}>Central & Tamil Nadu agricultural schemes — matched to your profile</p>
      <div style={{ padding:"10px 14px", background:C.pale, borderRadius:8, fontSize:13, color:C.bg2, marginBottom:16 }}>
        ✅ Your profile: {user.name} • {user.district} • {user.landSize||"?"} acres • {user.crops?.slice(0,3).join(", ")||"various crops"} — <strong>{SCHEMES.length} schemes available</strong>
      </div>
      {SCHEMES.map((s,i) => (
        <Card key={i} style={{ marginBottom:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }} onClick={() => setOpen(open===i?null:i)}>
            <div style={{ flex:1, marginRight:14, cursor:"pointer" }}>
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                <span style={{ fontSize:14.5, fontWeight:600, color:C.text }}>{s.name}</span>
                <Badge>{s.tag}</Badge>
                <Badge color={C.amber} bg={C.amberPale}>{s.amount}</Badge>
              </div>
              <div style={{ fontSize:13, color:C.muted, lineHeight:1.45 }}>{s.desc}</div>
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:7, alignItems:"flex-end", flexShrink:0 }}>
              <Badge color={C.bg2}>● Active</Badge>
              <button onClick={e=>{e.stopPropagation();window.open(s.portal,"_blank")}} style={{ padding:"6px 13px", background:C.bg2, color:"#fff", borderRadius:7, border:"none", cursor:"pointer", fontSize:12, fontWeight:500 }}>Apply →</button>
            </div>
          </div>
          {open === i && (

          <div style={{ marginTop:12, paddingTop:12, borderTop:`1px solid ${C.border}` }}>
              <div style={{ fontSize:12.5, fontWeight:600, color:C.text, marginBottom:6 }}>📄 Required Documents:</div>
              <div style={{ display:"flex", gap:7, flexWrap:"wrap", marginBottom:10 }}>
                {s.docs.map(d => <span key={d} style={{ padding:"4px 10px", background:C.bg, borderRadius:6, fontSize:12, color:C.text, border:`1px solid ${C.border}` }}>📄 {d}</span>)}
              </div>
              <div style={{ fontSize:12, color:C.muted }}>🌐 Portal: <a href={s.portal} target="_blank" rel="noreferrer" style={{ color:C.bg2 }}>{s.portal}</a></div>
            </div>
          )}
        </Card>
      ))}
    </div>
  );
}

export default Schemes;
